/**
 * The question engine against a real PostgreSQL (Phase 2.2): sessions,
 * rounds, questions and answers under row-level security, generated by a
 * deterministic fake generator (no model is ever called), deduplicated
 * against the book through the 2.0 vector store and the stub embedder.
 *
 *   a session runs its rounds: frontier → questions → answers → close →
 *   recomputed frontier, and ends saying why (FRONTIER_EMPTY,
 *   NOTHING_AT_DEPTH, ROUND_BUDGET, AUTHOR_STOPPED)
 *   the bible's stored values are never asked (rule 5)
 *   answers are append-only; a re-answer is a new revision
 *   question and answer text is ciphertext at rest
 *   with no model call possible (no key) nothing is written (503
 *   AI_UNAVAILABLE CREDENTIAL_NOT_CONFIGURED)
 *   the wired generator over 2.1 (interview-model-wiring.test.ts holds the
 *   calls, the ledger and the stops)
 *   another workspace sees nothing
 */
import { randomBytes } from 'node:crypto';
import { ZodError } from 'zod';
import { prisma } from '@/lib/db';
import { runInWorkspaceContext } from '@/lib/db/rls-middleware';
import { getVectorRepository } from '@/app-layer/repositories/vector.repository';
import { deleteBook } from '@/app-layer/usecases/books';
import { purgeDeletedBooks } from '@/app-layer/usecases/book-purge';
import { deleteElement } from '@/app-layer/usecases/bible-elements';
import { questionRecord, rebuildQuestionEmbeddings, type QuestionEmbedder } from '@/app-layer/usecases/question-embeddings';
import { vectorContentHash } from '@/lib/ai/embeddings/content-hash';
import { createBook } from '@/app-layer/usecases/books';
import { createElement } from '@/app-layer/usecases/bible-elements';
import { answerQuestion, decideLater, skipQuestion } from '@/app-layer/usecases/interview-answers';
import { closeRound, getInterview, listInterviews, nextRound, startInterview, stopInterview } from '@/app-layer/usecases/interviews';
import { embedderFrom } from '@/app-layer/usecases/question-embeddings';
import { StubEmbeddingProvider } from '@/lib/ai/embeddings/stub-provider';
import { AppError } from '@/lib/errors/types';
import { getTemplate } from '@/lib/bible/templates';
import type { InterviewView, QuestionView } from '@/app-layer/usecases/interview-state';
import { fakeGenerator, fakeQuestion } from '../helpers/fake-question-generator';
import { createAccount, workspaceCtx } from '../helpers/workspaces';

afterAll(() => prisma.$disconnect());

const embedder = embedderFrom(new StubEmbeddingProvider());

let owner: Awaited<ReturnType<typeof createAccount>>;
let stranger: Awaited<ReturnType<typeof createAccount>>;
let ctx: ReturnType<typeof workspaceCtx>;
let bookId: string;

beforeAll(async () => {
    owner = await createAccount();
    stranger = await createAccount();
    ctx = workspaceCtx(owner);
    bookId = (await createBook(ctx, { title: 'The Tuner’s Year' })).id;
});

async function character(name: string, fields: Array<{ key: string; value: unknown }> = []) {
    return createElement(ctx, bookId, { kind: 'CHARACTER', name, fields });
}

async function refusal(p: Promise<unknown>): Promise<{ status: number; reason: unknown }> {
    try {
        await p;
    } catch (err) {
        if (err instanceof AppError) return { status: err.status, reason: (err.details as { reason?: unknown } | undefined)?.reason };
        if (err instanceof ZodError) return { status: 400, reason: 'VALIDATION_ERROR' };
        throw err;
    }
    throw new Error('expected a refusal');
}

function targetsOf(view: InterviewView): string[] {
    return view.round!.questions.flatMap((q) => q.targetsFieldKeys);
}

describe('a session runs its rounds', () => {
    it('asks the frontier, recomputes it after answers, and ends saying why', async () => {
        const el = await character('Aurel Pask');
        const gen = fakeGenerator();
        const started = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 2, detail: 3 }, { generator: gen, embedder });
        expect(started.session.status).toBe('ACTIVE');
        expect(started.round!.number).toBe(1);
        // Depth 2, nothing stored: the level-1 fields (core first: role), each asked once.
        expect(targetsOf(started)[0]).toBe('role');
        expect(new Set(targetsOf(started)).size).toBe(targetsOf(started).length);
        expect(gen.calls).toHaveLength(1);
        // The author's text is data (2.1 fences it), never the system prompt or the task.
        expect(gen.calls[0].template.system).not.toContain('Aurel Pask');
        expect(gen.calls[0].template.task).not.toContain('Aurel Pask');
        expect(gen.calls[0].data.some((b) => b.text.includes('Aurel Pask'))).toBe(true);

        // Answer every question of the round, then close it.
        for (const q of started.round!.questions) await answerQuestion(ctx, bookId, started.session.id, q.id, answerFor(q));
        const closed = await closeRound(ctx, bookId, started.session.id, '1', {});
        expect(closed.session.roundsRun).toBe(1);
        expect(closed.session.status).toBe('ACTIVE');

        const second = await nextRound(ctx, bookId, started.session.id, { generator: gen, embedder });
        expect(second.round!.number).toBe(2);
        // Round 2 asks what the answered role unlocked, never role again.
        expect(targetsOf(second)).not.toContain('role');
        expect(targetsOf(second)).toEqual(expect.arrayContaining(['want', 'wound']));
        for (const q of second.round!.questions) await decideLater(ctx, bookId, started.session.id, q.id);
        const ended = await closeRound(ctx, bookId, started.session.id, '2', {});
        // Everything depth 2 reaches is answered or set aside.
        expect(ended.session.status).toBe('COMPLETED');
        expect(['FRONTIER_EMPTY', 'ROUND_BUDGET']).toContain(ended.session.stopReason);
        expect(ended.progress).toMatchObject({ status: 'MEASURED', deferred: second.round!.questions.length });
    });

    it('never asks what the bible already holds (rule 5)', async () => {
        const el = await character('Vera Pask', [
            { key: 'role', value: 'The tuner’s late wife, whose organ he keeps.' },
            { key: 'want', value: 'To hear the chapel organ sound once more.' },
        ]);
        const view = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 2, detail: 3 }, { generator: fakeGenerator(), embedder });
        expect(targetsOf(view)).not.toContain('role');
        expect(targetsOf(view)).not.toContain('want');
        expect(targetsOf(view)).toContain('wound');
    });

    it('ends at once, without the model, when nothing is in reach, and says it is too deep', async () => {
        const prominence = getTemplate('CHARACTER').fields.find((f) => f.key === 'prominence');
        const option = prominence?.type === 'choice' ? prominence.options[0].value : '';
        const el = await character('Ludmere Organist', [
            { key: 'role', value: 'Plays at the chapel.' },
            { key: 'prominence', value: option },
        ]);
        const notWired = { unavailableReason: () => 'CREDENTIAL_NOT_CONFIGURED', generateCandidates: async () => ({ output: {}, tokensUsed: 0 }) };
        // Depth 1: only `role` and `prominence` are in reach, and both are stored; everything else is deeper.
        const view = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 1, detail: 1 }, { generator: notWired, embedder });
        expect(view.session).toMatchObject({ status: 'COMPLETED', stopReason: 'NOTHING_AT_DEPTH' });
        expect(view.progress).toEqual({ status: 'NOT_ASSESSED', asked: 0 });
        expect((view.session.stopDetail as { tooDeep: unknown[] }).tooDeep.length).toBeGreaterThan(0);
    });

    it('stops when the author stops, keeping every answer', async () => {
        const el = await character('Stopped Early');
        const view = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 3, detail: 2 }, { generator: fakeGenerator(), embedder });
        const q = view.round!.questions[0];
        await answerQuestion(ctx, bookId, view.session.id, q.id, answerFor(q));
        const stopped = await stopInterview(ctx, bookId, view.session.id);
        expect(stopped.session).toMatchObject({ status: 'STOPPED', stopReason: 'AUTHOR_STOPPED' });
        expect(stopped.round!.questions[0].answer?.status).toBe('ANSWERED');
        expect((await refusal(nextRound(ctx, bookId, view.session.id, { generator: fakeGenerator(), embedder }))).reason).toBe('INTERVIEW_ENDED');
    });
});

describe('when no model call can be made (no API key: jest.setup.js clears it)', () => {
    it('the deployment generator refuses 503 AI_UNAVAILABLE naming the missing key, and writes nothing', async () => {
        const el = await character('Never Asked');
        const before = await prisma.interviewSession.count({ where: { workspaceId: owner.workspaceId } });
        const calls = await prisma.aiCallLog.count({ where: { workspaceId: owner.workspaceId } });
        const r = await refusal(startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id }));
        expect(r).toEqual({ status: 503, reason: 'CREDENTIAL_NOT_CONFIGURED' });
        expect(await prisma.interviewSession.count({ where: { workspaceId: owner.workspaceId } })).toBe(before);
        // Refused before any call: no AiCallLog row either.
        expect(await prisma.aiCallLog.count({ where: { workspaceId: owner.workspaceId } })).toBe(calls);
    });
});

function answerFor(q: QuestionView): { text?: string; choice?: string; scale?: number } {
    if (q.kind === 'CHOICE' || q.kind === 'EITHER_OR') return { choice: q.options![0] };
    if (q.kind === 'SCALE') return { scale: 3 };
    return { text: `An answer about ${q.targetsFieldKeys.join(' and ')}.` };
}

describe('isolation', () => {
    it('another workspace finds neither the session nor the book', async () => {
        const el = await character('Private');
        const view = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id }, { generator: fakeGenerator(), embedder });
        const other = workspaceCtx(stranger);
        expect((await refusal(getInterview(other, bookId, view.session.id))).status).toBe(404);
        expect((await refusal(listInterviews(other, bookId))).status).toBe(404);
        expect((await refusal(skipQuestion(other, bookId, view.session.id, view.round!.questions[0].id))).status).toBe(404);
    });
});



describe('answers', () => {
    async function openRound(detail = 3) {
        const el = await character(`Answerer ${randomBytes(3).toString('hex')}`);
        const gen = fakeGenerator({
            mutate: (q) =>
                q.targetsFieldKeys[0] === 'role'
                    ? { ...q, kind: 'CHOICE', text: 'Which job does this character do?', options: ['leads', 'opposes', 'helps'], recommendedAnswer: 'helps', recommendationBasis: { fieldKeys: [], answerIds: [] } }
                    : q,
        });
        const view = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 1, detail }, { generator: gen, embedder });
        return { view, sessionId: view.session.id, choice: view.round!.questions.find((q) => q.kind === 'CHOICE')!, el };
    }

    it('are append-only: a re-answer is the next revision, and the database refuses an edit or a delete', async () => {
        const { sessionId, choice } = await openRound();
        const first = await answerQuestion(ctx, bookId, sessionId, choice.id, { choice: 'leads' });
        const second = await answerQuestion(ctx, bookId, sessionId, choice.id, { choice: 'opposes', text: 'Because the wife wanted it.' });
        expect([first.answer?.revision, second.answer?.revision]).toEqual([1, 2]);
        const rows = await prisma.answer.findMany({ where: { questionId: choice.id }, orderBy: { revision: 'asc' }, take: 10 });
        expect(rows).toHaveLength(2);
        await expect(prisma.answer.update({ where: { id: rows[0].id }, data: { scale: 2 } })).rejects.toThrow(/ANSWER_APPEND_ONLY/);
        await expect(prisma.answer.delete({ where: { id: rows[0].id } })).rejects.toThrow(/ANSWER_APPEND_ONLY/);
        // app_user holds no UPDATE or DELETE at all.
        await expect(
            runInWorkspaceContext(ctx, (db) => db.$executeRaw`DELETE FROM "Answer" WHERE "id" = ${rows[0].id}`),
        ).rejects.toThrow(/permission denied/);
    });

    it('hold a pick to the options, a text to the detail dial, and take a recommendation as offered', async () => {
        const { sessionId, choice, view } = await openRound();
        expect((await refusal(answerQuestion(ctx, bookId, sessionId, choice.id, { choice: 'something new' }))).reason).toBe('NOT_AN_OPTION');
        expect((await refusal(answerQuestion(ctx, bookId, sessionId, choice.id, { scale: 3 }))).reason).toBe('ANSWER_SHAPE');
        const taken = await answerQuestion(ctx, bookId, sessionId, choice.id, { acceptRecommendation: true });
        expect(taken.answer).toMatchObject({ status: 'ANSWERED', choice: 'helps', acceptedRecommendation: true });
        const open = view.round!.questions.find((q) => q.kind === 'OPEN' || q.kind === 'SCALE');
        if (open?.kind === 'OPEN') {
            expect((await refusal(answerQuestion(ctx, bookId, sessionId, open.id, { text: 'x'.repeat(601) }))).reason).toBe('ANSWER_TOO_LONG');
            expect((await refusal(answerQuestion(ctx, bookId, sessionId, open.id, { text: '<b></b>' }))).reason).toBe('ANSWER_REQUIRED');
            expect((await refusal(answerQuestion(ctx, bookId, sessionId, open.id, { acceptRecommendation: true }))).reason).toBe('NO_RECOMMENDATION');
        }
    });

    it('are sanitised and stored as ciphertext, with the question text', async () => {
        const { sessionId, choice } = await openRound();
        await answerQuestion(ctx, bookId, sessionId, choice.id, { choice: 'leads', text: 'He <script>alert(1)</script>keeps the key.' });
        const [raw] = await prisma.$queryRaw<Array<{ text: string; choice: string }>>`SELECT "text", "choice" FROM "Answer" WHERE "questionId" = ${choice.id}`;
        expect(raw.text.startsWith('v2:')).toBe(true);
        expect(raw.choice.startsWith('v2:')).toBe(true);
        const [q] = await prisma.$queryRaw<Array<{ text: string; options: string }>>`SELECT "text", "options" FROM "Question" WHERE "id" = ${choice.id}`;
        expect(q.text.startsWith('v2:')).toBe(true);
        expect(q.options.startsWith('v2:')).toBe(true);
        const view = await getInterview(ctx, bookId, sessionId);
        expect(view.round!.questions.find((x) => x.id === choice.id)!.answer!.text).toBe('He keeps the key.');
    });

    it('a round closes only when every question has a status; then its answers stand', async () => {
        const { sessionId, choice, view } = await openRound();
        await skipQuestion(ctx, bookId, sessionId, choice.id);
        if (view.round!.questions.length > 1) {
            expect(await refusal(closeRound(ctx, bookId, sessionId, '1', {}))).toEqual({ status: 409, reason: 'ROUND_HAS_UNANSWERED' });
        }
        const closed = await closeRound(ctx, bookId, sessionId, '1', { skipUnanswered: true });
        expect(closed.round!.questions.every((q) => q.answer?.status === 'SKIPPED')).toBe(true);
        expect((await refusal(answerQuestion(ctx, bookId, sessionId, choice.id, { choice: 'leads' }))).status).toBe(409);
        expect((await refusal(closeRound(ctx, bookId, sessionId, '1', {}))).status).toBe(409);
    });

    it('go with their element: deleting it deletes its questions, answers and question vectors', async () => {
        const { sessionId, choice, el } = await openRound();
        await answerQuestion(ctx, bookId, sessionId, choice.id, { choice: 'leads' });
        expect(await prisma.vectorEmbedding.count({ where: { sourceModel: 'Question', sourceId: choice.id } })).toBe(1);
        await deleteElement(ctx, bookId, el.id);
        expect(await prisma.question.count({ where: { sessionId } })).toBe(0);
        expect(await prisma.answer.count({ where: { sessionId } })).toBe(0);
        expect(await prisma.interviewSession.count({ where: { id: sessionId } })).toBe(0);
        expect(await prisma.vectorEmbedding.count({ where: { sourceModel: 'Question', sourceId: choice.id } })).toBe(0);
    });

    it('go with their book when it is purged', async () => {
        const doomedBook = (await createBook(ctx, { title: 'Doomed' })).id;
        const el = await createElement(ctx, doomedBook, { kind: 'THEME', name: 'Loss' });
        const view = await startInterview(ctx, doomedBook, { scope: 'ELEMENT', elementId: el.id, depth: 1, detail: 2 }, { generator: fakeGenerator(), embedder });
        await answerQuestion(ctx, doomedBook, view.session.id, view.round!.questions[0].id, { text: 'Grief and attention.' });
        await deleteBook(ctx, doomedBook);
        await prisma.book.update({ where: { id: doomedBook }, data: { deletedAt: new Date(Date.now() - 31 * 24 * 60 * 60 * 1000) } });
        await purgeDeletedBooks();
        expect(await prisma.interviewSession.count({ where: { bookId: doomedBook } })).toBe(0);
        expect(await prisma.answer.count({ where: { sessionId: view.session.id } })).toBe(0);
    });
});

describe('scopes and dials', () => {
    it('a kind the book has none of is refused, not completed over nothing (rule 6)', async () => {
        const empty = (await createBook(ctx, { title: 'Empty' })).id;
        expect((await refusal(startInterview(ctx, empty, { scope: 'KIND', kind: 'FACTION' }, { generator: fakeGenerator(), embedder }))).reason).toBe('SCOPE_EMPTY');
        expect((await refusal(startInterview(ctx, empty, { scope: 'BOOK' }, { generator: fakeGenerator(), embedder }))).reason).toBe('SCOPE_EMPTY');
    });

    it('a kind session asks about every element of the kind, in creation order', async () => {
        const kindBook = (await createBook(ctx, { title: 'Two settings' })).id;
        const a = await createElement(ctx, kindBook, { kind: 'SETTING', name: 'The chapel' });
        const b = await createElement(ctx, kindBook, { kind: 'SETTING', name: 'The shut shop' });
        const view = await startInterview(ctx, kindBook, { scope: 'KIND', kind: 'SETTING', depth: 1, detail: 1 }, { generator: fakeGenerator(), embedder });
        const elements = view.round!.questions.map((q) => q.elementId);
        expect(elements).toContain(a.id);
        expect(elements).toContain(b.id);
        expect(elements.indexOf(a.id)).toBeLessThan(elements.indexOf(b.id));
        // Detail 1 asks picks and numbers only.
        expect(view.round!.questions.every((q) => ['CHOICE', 'EITHER_OR', 'SCALE'].includes(q.kind))).toBe(true);
    });

    it('a persona is stored on the session and its pack goes into the system prompt', async () => {
        const el = await character('Persona Subject');
        const gen = fakeGenerator();
        const view = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, personaKeys: ['socratic'] }, { generator: gen, embedder });
        expect(view.session.personaKeys).toEqual(['socratic']);
        expect(gen.calls[0].template.system).toContain('# Socratic');
        expect(view.round!.questions.every((q) => q.personaKey === 'socratic' || q.origin === 'PACK_FALLBACK')).toBe(true);
        expect((await refusal(startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, personaKeys: ['the-critic'] }, { generator: gen, embedder }))).status).toBe(400);
    });
});

describe('when generation goes wrong', () => {
    it('a failed call falls back to the craft pack’s own examples', async () => {
        const el = await character('Fallback');
        const view = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 1, detail: 1 }, { generator: fakeGenerator({ fail: true }), embedder });
        expect(view.session.status).toBe('ACTIVE');
        expect(view.round!.questions.length).toBeGreaterThan(0);
        expect(view.round!.questions.every((q) => q.origin === 'PACK_FALLBACK' && q.recommendedAnswer === null)).toBe(true);
    });

    it('a round nothing could be asked in pauses the session, which resumes with the next round', async () => {
        // Depth 1 with the role stored leaves only `prominence`, which the character pack has no example for:
        // with every call failing, nothing can be asked.
        const el = await character('Unaskable', [{ key: 'role', value: 'Keeps the ferry log.' }]);
        const view = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 1, detail: 1 }, { generator: fakeGenerator({ fail: true }), embedder });
        expect(view.session).toMatchObject({ status: 'PAUSED', stopReason: 'PROVIDER_FAILURE' });
        expect(view.round).toBeNull();
        const resumed = await nextRound(ctx, bookId, view.session.id, { generator: fakeGenerator(), embedder });
        expect(resumed.session).toMatchObject({ status: 'ACTIVE', stopReason: null });
        expect(resumed.round).toMatchObject({ number: 2 });
        expect(resumed.round!.questions.map((q) => q.targetsFieldKeys)).toEqual([['prominence']]);
    });

    it('two requests for the next round generate it once', async () => {
        const el = await character('Raced');
        const start = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 3, detail: 3 }, { generator: fakeGenerator(), embedder });
        for (const q of start.round!.questions) await answerQuestion(ctx, bookId, start.session.id, q.id, answerFor(q));
        await closeRound(ctx, bookId, start.session.id, '1', {});
        let release!: () => void;
        const gate = new Promise<void>((r) => (release = r));
        const slow = fakeGenerator();
        const slowGen = { unavailableReason: () => null, generateCandidates: async (req: Parameters<typeof slow.generateCandidates>[0]) => (await gate, slow.generateCandidates(req)) };
        const first = nextRound(ctx, bookId, start.session.id, { generator: slowGen, embedder });
        await new Promise((r) => setTimeout(r, 300));
        const second = await refusal(nextRound(ctx, bookId, start.session.id, { generator: slowGen, embedder }));
        release();
        await first;
        expect(second).toEqual({ status: 409, reason: 'ROUND_GENERATING' });
        expect(await prisma.interviewRound.count({ where: { sessionId: start.session.id } })).toBe(2);
    });
});

describe('deduplication against the book (the vector store)', () => {
    it('a question asked in an earlier session is not asked again in the same words', async () => {
        const el = await character('Asked Twice');
        const first = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 1, detail: 2 }, { generator: fakeGenerator(), embedder });
        await stopInterview(ctx, bookId, first.session.id);
        // The field is still empty, so a new session asks it again — but the fake words it the same way.
        const second = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 1, detail: 2 }, { generator: fakeGenerator(), embedder });
        const firstTexts = new Set(first.round!.questions.map((q) => q.text));
        expect(second.round!.questions.some((q) => firstTexts.has(q.text))).toBe(false);
        const round = await prisma.interviewRound.findFirst({ where: { sessionId: second.session.id }, select: { metrics: true } });
        expect((round!.metrics as { duplicates: Record<string, number> }).duplicates.EXACT).toBeGreaterThan(0);
    });

    it('a reworded repeat the embedding finds is dropped too', async () => {
        // An embedder that maps every question about "heart" to one direction: a paraphrase the words alone would not catch.
        const vector = (t: string) => (/heart/i.test(t) ? [1, 0, 0, 0] : t.length % 2 === 0 ? [0, 1, 0, 0] : [0, 0, 1, 0]);
        const paraphrases: QuestionEmbedder = { revision: 'paraphrase-test:d4:p00000000', embed: async (texts) => texts.map(vector) };
        const el = await character('Heartfelt');
        const ask = (text: string) =>
            fakeGenerator({ mutate: (q) => (q.targetsFieldKeys[0] === 'role' ? { ...fakeQuestion(q.elementId, 'role', ['OPEN']), text } : q) });
        const first = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 1, detail: 2 }, { generator: ask('Where does the heart of this character lie?'), embedder: paraphrases });
        await stopInterview(ctx, bookId, first.session.id);
        const second = await startInterview(ctx, bookId, { scope: 'ELEMENT', elementId: el.id, depth: 1, detail: 2 }, { generator: ask('What is at the heart of their part in events?'), embedder: paraphrases });
        const role = second.round!.questions.find((q) => q.targetsFieldKeys.includes('role'))!;
        expect(role.text).not.toBe('What is at the heart of their part in events?');
        expect(role.origin).toBe('PACK_FALLBACK');
        const round = await prisma.interviewRound.findFirst({ where: { sessionId: second.session.id }, select: { metrics: true } });
        expect((round!.metrics as { duplicates: Record<string, number> }).duplicates.EMBEDDING).toBe(1);
    });
});

describe('question vectors live and die with the question (issue #23, item 1)', () => {
    it('the store refuses a vector for a question that does not exist, and a rebuild skips one', async () => {
        const rec = questionRecord(`gone-${randomBytes(4).toString('hex')}`, bookId, 'A question nobody asked?', [1, 0, 0], 'guard-test:d3:p00000000');
        await expect(runInWorkspaceContext(ctx, (db) => getVectorRepository().upsert(db, ctx.workspaceId, [rec]))).rejects.toThrow(/VECTOR_SOURCE_MISSING/);
        const outcome = await getVectorRepository().rebuildRevision((fn) => runInWorkspaceContext(ctx, fn), ctx.workspaceId, 'guard-test:d3:p00000000', [[rec]], { allowEmpty: true });
        // Seen, but nothing written — and nothing counted as written.
        expect(outcome).toEqual({ inserted: 0, updated: 0, unchanged: 0, deleted: 0, seen: 1 });
        expect(await prisma.vectorEmbedding.count({ where: { sourceId: rec.sourceId } })).toBe(0);
    });

    it('a rebuild re-embeds every existing question and brings back no deleted one', async () => {
        const isolatedOwner = await createAccount();
        const ictx = workspaceCtx(isolatedOwner);
        const ibook = (await createBook(ictx, { title: 'Rebuilt' })).id;
        const el = await createElement(ictx, ibook, { kind: 'CHARACTER', name: 'Kept' });
        const doomed = await createElement(ictx, ibook, { kind: 'CHARACTER', name: 'Doomed' });
        const kept = await startInterview(ictx, ibook, { scope: 'ELEMENT', elementId: el.id, depth: 1, detail: 2 }, { generator: fakeGenerator(), embedder });
        await startInterview(ictx, ibook, { scope: 'ELEMENT', elementId: doomed.id, depth: 1, detail: 2 }, { generator: fakeGenerator(), embedder });
        // A rebuild under a new revision whose source still names a question deleted after it was read.
        const doomedQuestions = await prisma.question.findMany({ where: { elementId: doomed.id }, select: { id: true, text: true }, take: 20 });
        const revision = 'rebuild-guard:d64:p00000000';
        const late = doomedQuestions.map((q) => questionRecord(q.id, ibook, 'stale text', new Array(64).fill(0).map((_, i) => (i === 0 ? 1 : 0)), revision));
        await deleteElement(ictx, ibook, doomed.id);
        const skipped = await getVectorRepository().rebuildRevision((fn) => runInWorkspaceContext(ictx, fn), ictx.workspaceId, revision, [late], { allowEmpty: true });
        expect(skipped).toMatchObject({ inserted: 0, updated: 0, unchanged: 0, seen: late.length });
        expect(await prisma.vectorEmbedding.count({ where: { embeddingRevision: revision } })).toBe(0);

        const result = await rebuildQuestionEmbeddings(ictx, { embedder });
        expect(result.rebuilt).toBe(true);
        const ids = kept.round!.questions.map((q) => q.id);
        expect(await prisma.vectorEmbedding.count({ where: { workspaceId: ictx.workspaceId, sourceModel: 'Question', embeddingRevision: embedder.revision } })).toBe(ids.length);
        const one = await prisma.vectorEmbedding.findFirst({ where: { sourceId: ids[0] }, select: { contentHash: true } });
        expect(one!.contentHash).toBe(vectorContentHash(kept.round!.questions[0].text));
    });
});
